"use client";
import { confirm } from "../../../../host/ui-slots.js";
import { requestSurfaceNavigation } from "../../../redux/surfaces/request-surface-navigation.thunk.js";
async function promptForkOutcome({
  dispatch,
  surfaceKey,
  newConversationId
}) {
  const goToBranch = await confirm({
    title: "Branch created",
    description: "Everything up to this message was duplicated into a new conversation. Open the new branch now, or stay in this one?",
    confirmLabel: "Go to new branch",
    cancelLabel: "Stay here"
  });
  if (!goToBranch) {
    return;
  }
  void dispatch(
    requestSurfaceNavigation({
      surfaceKey,
      conversationId: newConversationId,
      reason: "fork"
    })
  );
}
export {
  promptForkOutcome
};
